def test_pathological_hard_link_emph(run):
    r = run(args=[], stdin=b'**x [a*b**c*](d)')
    assert r.stdout == b'<p>**x <a href="d">a<em>b**c</em></a></p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


